attributes.onClick:
{() => {
            const parts = askText.split(/\n+/).map((p) => p.trim()).filter(Boolean);
            const first = compilePhrase(parts[0] ?? askText);
            useEkas.getState().setQuery(first);
            useEkas.setState({
              askThread: parts.map((q) => ({
                q,
                note: "Compiled to the model. A move is located only if compare is on. Cause is not established.",
              })),
            });
            useEkas.getState().log("Ask run");
          }}

