attributes.onChange:
{async (e) => {
            const file = e.target.files?.[0];
            if (!file) return;
            const text = await file.text();
            toast(text.includes("synonyms") ? "Synonyms file read. Applied as a note only." : "File did not contain synonyms.");
            useEkas.getState().log("Import synonyms");
          }}

