attributes.onClick:
{() => {
          const text = sql.toLowerCase();
          if (text.includes("drop ") || text.includes("delete ") || text.includes(";")) {
            setMsg("Refused. Studio runs the governed model only.");
            return;
          }
          useEkas.getState().setQuery({ ...emptyQuery(), columns: ["revenue", "region"], title: "Studio" });
          setMsg("Ran the governed revenue-by-region query. The text box is not a free SQL engine.");
          useEkas.getState().log("Studio run");
        }}

